<script setup lang="ts">
import {ref} from 'vue';
import {ChevronRight,Database,FolderOpen,LayoutDashboard,Table2,CalendarClock,LockKeyhole,Server} from 'lucide-vue-next';
type Item=Record<string,any>;
defineProps<{overview?:Item;related?:Item[]}>();
const emit=defineEmits<{open:[item:Item]}>();
const searches=ref<Record<string,string>>({});const limits=ref<Record<string,number>>({});
function matching(group:Item):Item[]{const query=(searches.value[group.label]??'').toLocaleLowerCase('pt-BR');return group.items.filter((item:Item)=>[item.name,item.ref,item.description,...(item.dashboards??[]).map((d:Item)=>d.name)].join(' ').toLocaleLowerCase('pt-BR').includes(query));}
function visible(group:Item){return matching(group).slice(0,limits.value[group.label]??8);}
function icon(kind:string){return ({app:LayoutDashboard,table:Table2,flow:Database,schedule:CalendarClock,credential:LockKeyhole,agent:Server} as Record<string,any>)[kind]??FolderOpen;}
function format(fact:Item){if(fact.format==='date'){const value=new Date(fact.value);return Number.isNaN(value.getTime())?fact.value:value.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});}return fact.format==='number'?Number(fact.value).toLocaleString('pt-BR'):fact.value;}
</script>
<template>
 <div class="resource-overview">
  <dl v-if="overview?.facts?.length" class="resource-facts"><div v-for="fact in overview.facts" :key="fact.label"><dt>{{fact.label}}</dt><dd>{{format(fact)}}</dd></div></dl>
  <section v-for="group in related??[]" :key="group.label" class="resource-related"><header><h3>{{group.label}}</h3><span>{{group.count===null?'Indisponível':group.count+(group.complete?'':' encontrados')}}</span></header><p v-if="group.status!=='available'" class="resource-note">{{group.reason||'Seu acesso não permite consultar esta área.'}}</p><template v-else><p v-if="!group.complete" class="resource-note">A lista pode estar incompleta: nem todos os vínculos foram disponibilizados para sua conta.</p><p v-if="!group.items.length" class="resource-note">{{group.complete?'Nenhum recurso vinculado.':'Nenhum vínculo identificado nesta consulta.'}}</p><input v-if="group.items.length>8" v-model="searches[group.label]" class="resource-related-search" :aria-label="'Buscar em '+group.label" placeholder="Buscar nesta lista…"><button v-for="item in visible(group)" :key="item.ref" class="resource-related-row" @click="emit('open',item)"><component :is="icon(item.kind)" :size="18"/><span><strong>{{item.name}}</strong><small v-if="item.kind==='app'&&item.dashboard_count!==null">{{item.dashboard_count}} {{item.dashboard_count===1?'dashboard':'dashboards'}}<template v-if="item.dashboards?.length"> · {{item.dashboards.map((d:Item)=>d.name).join(', ')}}</template></small><small v-else>{{item.description||item.ref}}</small></span><ChevronRight :size="16"/></button><p v-if="group.items.length&&!matching(group).length" class="resource-note">Nenhum resultado para esta busca.</p><button v-if="matching(group).length>visible(group).length" class="resource-show-more" @click="limits[group.label]=(limits[group.label]??8)+20">Mostrar mais · {{matching(group).length-visible(group).length}} restantes</button></template></section>
  <section v-if="overview?.columns_available" class="resource-schema"><header><h3>Estrutura dos dados</h3><span>{{overview.columns.length}} campos</span></header><div v-if="overview.columns.length" class="catalog-table-scroll"><table><thead><tr><th>Campo</th><th>Nome de exibição</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr v-for="column in overview.columns" :key="column.name"><td><code>{{column.name}}</code></td><td>{{column.label}}</td><td>{{column.type||'Não informado'}}</td><td>{{column.description||'—'}}</td></tr></tbody></table></div><p v-else class="resource-note">A estrutura não contém campos nesta consulta.</p></section>
  <section v-if="overview?.nodes_available" class="resource-etl"><header><h3>Etapas do ETL</h3><span>{{overview.nodes.length}} etapas</span></header><ol v-if="overview.nodes.length"><li v-for="(node,index) in overview.nodes" :key="node.id"><span class="resource-step-number">{{Number(index)+1}}</span><div><strong>{{node.name}}</strong><small>{{node.type}}<template v-if="node.rows!==null"> · {{Number(node.rows).toLocaleString('pt-BR')}} linhas</template></small><small v-if="node.executed_at">Última execução informada: {{format({value:node.executed_at,format:'date'})}}</small></div></li></ol><p v-else class="resource-note">Nenhuma etapa foi disponibilizada.</p></section>
 </div>
</template>
